python -c 'from zipfile import ZipFile; from lxml import etree; p="/work/complaint_preparation.docx"; ns={"w":"http://schemas.openxmlformats.org/wordprocessingml/2006/main"}; expected={"ascii","hAnsi","eastAsia","cs"}
with ZipFile(p) as z:
 bad=[]; root=etree.fromstring(z.read("word/document.xml"))
 for r in root.xpath(".//w:r[w:t]",namespaces=ns):
  txt="".join(r.xpath("./w:t/text()",namespaces=ns)); rf=r.find("w:rPr/w:rFonts",ns)
  vals={} if rf is None else {k:rf.get("{"+ns["w"]+"}"+k) for k in expected}
  if set(vals)!=expected or len(set(vals.values()))!=1 or next(iter(vals.values())) not in ("SimHei","FangSong"): bad.append((txt,vals))
 print("text-bearing run font failures:",len(bad)); print(bad[:5])
 print("zip integrity:",z.testzip())'

